import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DStH8c-G.js";var i=JSON.parse(`{"title":"Class: InboundFeaturePatches<TPatch>","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: InboundFeaturePatches<TPatch>"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/InboundFeaturePatches"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/chunkgen/classes/InboundFeaturePatches"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/chunkgen/src"}},"headers":[],"relativePath":"api/@jsprismarine/chunkgen/classes/InboundFeaturePatches.md","filePath":"api/@jsprismarine/chunkgen/classes/InboundFeaturePatches.md","lastUpdated":1794433523000}`),a={name:`api/@jsprismarine/chunkgen/classes/InboundFeaturePatches.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/chunkgen</a> / InboundFeaturePatches</p><h1 id="class-inboundfeaturepatches-tpatch" tabindex="-1">Class: InboundFeaturePatches&lt;TPatch&gt; <a class="header-anchor" href="#class-inboundfeaturepatches-tpatch" aria-label="Permalink to “Class: InboundFeaturePatches&lt;TPatch&gt;”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/chunkgen/src/FeaturePatch.ts#L84" target="_blank" rel="noreferrer">FeaturePatch.ts:84</a></p><p>The feature writes a chunk&#39;s eight neighbors owe it, kept until the chunk is finished.</p><p>This is the half of the patch merge that decides the answer, and the only thing it decides is order. A feature pass that reaches across a border records what it wrote rather than writing it, and the patch waits here until the target chunk is promoted. The target then applies its own post-<code>features</code> state first and these eight after it, in <a href="./../#feature-patch-order">FEATURE_PATCH_ORDER</a>, which is what makes a tree rooted in one chunk come out whole in the next.</p><p>Storing by source offset rather than appending to a list is the mechanism, not an implementation detail. A list would record arrival order, and arrival order is what the scheduler chooses.</p><h2 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h2><h3 id="tpatch" tabindex="-1">TPatch <a class="header-anchor" href="#tpatch" aria-label="Permalink to “TPatch”">​</a></h3><p><code>TPatch</code></p><p>What a patch is, which this class never looks inside. The server&#39;s patch carries Java block states with properties; a worker&#39;s would carry palette indices.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new InboundFeaturePatches</strong>&lt;<code>TPatch</code>&gt;(): <code>InboundFeaturePatches</code>&lt;<code>TPatch</code>&gt;</p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>InboundFeaturePatches</code>&lt;<code>TPatch</code>&gt;</p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="size" tabindex="-1">size <a class="header-anchor" href="#size" aria-label="Permalink to “size”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>size</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/chunkgen/src/FeaturePatch.ts#L88" target="_blank" rel="noreferrer">FeaturePatch.ts:88</a></p><p>How many of the eight neighbors have handed theirs over.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="has" tabindex="-1">has() <a class="header-anchor" href="#has" aria-label="Permalink to “has()”">​</a></h3><blockquote><p><strong>has</strong>(<code>dx</code>, <code>dz</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/chunkgen/src/FeaturePatch.ts#L93" target="_blank" rel="noreferrer">FeaturePatch.ts:93</a></p><p>Whether a neighbor at this offset has handed one over.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="dx" tabindex="-1">dx <a class="header-anchor" href="#dx" aria-label="Permalink to “dx”">​</a></h5><p><code>number</code></p><h5 id="dz" tabindex="-1">dz <a class="header-anchor" href="#dz" aria-label="Permalink to “dz”">​</a></h5><p><code>number</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="inmergeorder" tabindex="-1">inMergeOrder() <a class="header-anchor" href="#inmergeorder" aria-label="Permalink to “inMergeOrder()”">​</a></h3><blockquote><p><strong>inMergeOrder</strong>(): readonly <code>TPatch</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/chunkgen/src/FeaturePatch.ts#L119" target="_blank" rel="noreferrer">FeaturePatch.ts:119</a></p><p>The patches to apply, in <a href="./../#feature-patch-order">FEATURE_PATCH_ORDER</a>.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>TPatch</code>[]</p><p>One entry per neighbor that wrote something, skipping those that wrote nothing. The order is positional, so it is the same list whatever order the patches arrived in.</p><hr><h3 id="receive" tabindex="-1">receive() <a class="header-anchor" href="#receive" aria-label="Permalink to “receive()”">​</a></h3><blockquote><p><strong>receive</strong>(<code>dx</code>, <code>dz</code>, <code>patch</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/chunkgen/src/FeaturePatch.ts#L106" target="_blank" rel="noreferrer">FeaturePatch.ts:106</a></p><p>Takes the patch a neighbor&#39;s feature pass wrote into this chunk.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="dx-1" tabindex="-1">dx <a class="header-anchor" href="#dx-1" aria-label="Permalink to “dx”">​</a></h5><p><code>number</code></p><p>Chunk offset on x from this chunk to the neighbor that wrote it.</p><h5 id="dz-1" tabindex="-1">dz <a class="header-anchor" href="#dz-1" aria-label="Permalink to “dz”">​</a></h5><p><code>number</code></p><p>Chunk offset on z.</p><h5 id="patch" tabindex="-1">patch <a class="header-anchor" href="#patch" aria-label="Permalink to “patch”">​</a></h5><p><code>TPatch</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>FeaturePatchOutOfRangeError when the offset is not one of the eight neighbors.</p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>DuplicateFeaturePatchError when that neighbor already handed one over, which means its <code>features</code> body ran twice.</p>`,63)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};